#!/usr/bin/env python3\n\"\"\"\nSimple ML Test Debug Script\n\"\"\"\n\nimport os\nos.environ['TF_ENABLE_ONEDNN_OPTS'] = '0'\n\nimport asyncio\nimport sys\nimport time\nfrom pathlib import Path\nimport numpy as np\n\n# Add project root to path\nsys.path.append(str(Path(__file__).parent))\n\nprint(\"Starting simple ML debug test...\")\n\ntry:\n    print(\"1. Importing modules...\")\n    from models.predictor_interface import PredictionType, ModelType, ModelConfig\n    from models import get_available_models, create_model\n    print(f\"   Available models: {get_available_models()}\")\n    \n    print(\"2. Creating XGBoost config...\")\n    from models.ensemble_model import create_xgboost_config\n    \n    config = create_xgboost_config(\n        prediction_type=PredictionType.RETURN_REGRESSION,\n        n_estimators=50,\n        max_depth=3,\n        learning_rate=0.1,\n        sequence_length=20,\n        features_dim=13\n    )\n    print(f\"   Config created: {config.model_type}\")\n    \n    print(\"3. Creating model...\")\n    model = create_model(config)\n    print(f\"   Model created successfully\")\n    \n    print(\"4. Generating test data...\")\n    np.random.seed(42)\n    n_samples = 500\n    sequence_length = 20\n    features_dim = 13\n    \n    # Generate simple data\n    X = np.random.randn(n_samples, sequence_length * features_dim)\n    y = np.random.randn(n_samples) * 0.01\n    \n    # Split data\n    train_size = int(0.8 * n_samples)\n    X_train, X_val = X[:train_size], X[train_size:]\n    y_train, y_val = y[:train_size], y[train_size:]\n    \n    print(f\"   Data shapes: X_train={X_train.shape}, y_train={y_train.shape}\")\n    \n    async def run_test():\n        print(\"5. Training model...\")\n        start_time = time.time()\n        training_metrics = await model.train(X_train, y_train, X_val, y_val)\n        training_time = time.time() - start_time\n        print(f\"   Training completed in {training_time:.2f}s\")\n        print(f\"   Train loss: {training_metrics.train_loss:.6f}\")\n        print(f\"   Val loss: {training_metrics.val_loss:.6f}\")\n        \n        print(\"6. Testing prediction...\")\n        start_time = time.time()\n        prediction = await model.predict(X_val[:1])\n        inference_time = time.time() - start_time\n        print(f\"   Prediction: {prediction[0]:.6f}\")\n        print(f\"   Inference time: {inference_time:.4f}s\")\n        \n        print(\"7. Testing batch prediction...\")\n        start_time = time.time()\n        batch_predictions = await model.predict(X_val[:5])\n        batch_time = time.time() - start_time\n        print(f\"   Batch predictions: {len(batch_predictions)} predictions\")\n        print(f\"   Batch time: {batch_time:.4f}s\")\n        \n        return True\n    \n    print(\"Running async test...\")\n    success = asyncio.run(run_test())\n    \n    if success:\n        print(\"\\nSUCCESS: Simple ML test completed successfully!\")\n    else:\n        print(\"\\nFAILED: Simple ML test failed!\")\n        \nexcept Exception as e:\n    print(f\"\\nERROR in simple ML test: {e}\")\n    import traceback\n    traceback.print_exc()\n\nprint(\"Debug test finished.\") 